add("fr","B1","Deyimler","le jardin a commencé à fleurir","bahçe çiçek açmaya başladı","ifade","Le jardin a commencé à fleurir ce printemps.","Bu ilkbaharda bahçe çiçek açmaya başladı.");
add("fr","B1","Deyimler","je travaille sur moi-même chaque jour","her gün kendim üzerinde çalışıyorum","ifade","Je travaille sur moi-même chaque jour maintenant.","Şu an her gün kendim üzerinde çalışıyorum.");
add("fr","B1","Deyimler","je suis sorti de ma zone de confort","konfor alanımdan çıktım","ifade","Je suis enfin sorti de ma zone de confort.","Sonunda konfor alanımdan çıktım.");
add("fr","B1","Deyimler","je suis devenu plus fort après cette expérience","bu deneyimden sonra daha güçlü oldum","ifade","Je suis devenu beaucoup plus fort après cette expérience.","Bu deneyimden sonra çok daha güçlü oldum.");
add("fr","B1","Deyimler","chaque difficulté nous apprend quelque chose","her zorluk bize bir şey öğretir","ifade","Chaque difficulté nous apprend quelque chose d'important.","Her zorluk bize önemli bir şey öğretir.");
